(function(root){
  'use strict';
  const mean=xs=>xs.length?xs.reduce((a,b)=>a+b,0)/xs.length:null;
  const median=xs=>{if(!xs.length)return null;const a=[...xs].sort((a,b)=>a-b),m=Math.floor(a.length/2);return a.length%2?a[m]:(a[m-1]+a[m])/2;};
  function filter(rows,f){return rows.filter(r=>(!f.market||String(r.country)===String(f.market))&&(!f.city||r.city===f.city)&&(!f.cuisine||r.cuisines.includes(f.cuisine))&&(!f.price||r.priceRange===Number(f.price))&&(!f.delivery||String(r.delivery)===f.delivery)&&(!f.booking||String(r.booking)===f.booking)&&(!f.rating||(r.rating!==null&&r.rating>=Number(f.rating)))&&(!f.search||[r.name,r.city,r.locality,...r.cuisines].join(' ').toLocaleLowerCase().includes(f.search.toLocaleLowerCase())));}
  function metrics(rows){const rated=rows.filter(r=>r.rating!==null),markets=new Set(rows.map(r=>r.country));const priceComparable=markets.size===1&&![162].includes(rows[0]?.country);return {count:rows.length,cities:new Set(rows.map(r=>r.city)).size,rated:rated.length,avgRating:mean(rated.map(r=>r.rating)),medianCost:priceComparable?median(rows.filter(r=>r.cost!==null).map(r=>r.cost)):null,priceComparable,delivery:rows.length?rows.filter(r=>r.delivery).length/rows.length:null,booking:rows.length?rows.filter(r=>r.booking).length/rows.length:null,votes:rows.reduce((a,r)=>a+r.votes,0),unrated:rows.length-rated.length};}
  function groups(rows,key){const g=new Map();for(const r of rows){for(const k of (key==='cuisines'?r.cuisines:[r[key]])){if(!g.has(k))g.set(k,[]);g.get(k).push(r);}}return [...g].map(([name,items])=>({name,...metrics(items)})).sort((a,b)=>b.count-a.count||String(a.name).localeCompare(String(b.name)));}
  function distribution(rows){const groups=[{name:'Unrated',color:'#a4acb9',count:0},{name:'Below 2.5',color:'#d64b50',count:0},{name:'2.5–3.4',color:'#eaa24d',count:0},{name:'3.5–3.9',color:'#5e9b94',count:0},{name:'4.0–4.4',color:'#328677',count:0},{name:'4.5–5.0',color:'#175b50',count:0}];for(const r of rows)groups[r.rating===null?0:r.rating<2.5?1:r.rating<3.5?2:r.rating<4?3:r.rating<4.5?4:5].count++;return groups;}
  const api={mean,median,filter,metrics,groups,distribution};if(typeof module!=='undefined')module.exports=api;root.ZomatoAnalytics=api;
})(typeof window!=='undefined'?window:globalThis);
